def program(xs):
    n = len(xs)
    if n < 2:
        return []
    # Find the end of the longest strictly increasing prefix
    l = 0
    while l + 1 < n and xs[l] < xs[l + 1]:
        l += 1
    # If the whole list is strictly increasing, nothing to return
    if l == n - 1:
        return []
    # Find the start of the longest strictly decreasing suffix
    r = n - 1
    while r - 1 >= 0 and xs[r - 1] > xs[r]:
        r -= 1
    # If the whole list is strictly decreasing, nothing to return
    if r == 0:
        return []
    # The middle part is between the increasing prefix and decreasing suffix
    if l + 1 >= r:
        return []
    return xs[l + 1:r]

