import sys

def program(xs):
    n = len(xs)
    # Step 1: find first drop (xs[i] > xs[i+1])
    start = None
    for i in range(n - 1):
        if xs[i] > xs[i + 1]:
            start = i + 1  # first element after the drop
            break
    if start is None:
        return []
    # Step 2: extend while non‑increasing (xs[k] >= xs[k+1])
    end = start
    while end < n - 1 and xs[end] >= xs[end + 1]:
        end += 1
    # The slice should include xs[end] (the last element of the decreasing run)
    return xs[start:end + 1]

