def program(xs):
    """Return a copy of xs with either the first element that repeats the previous one removed,
    or, if there is no such repeat, the element at index 2 (the third element) removed.
    """
    n = len(xs)
    # Look for the first consecutive duplicate
    for i in range(1, n):
        if xs[i] == xs[i - 1]:
            return xs[:i] + xs[i + 1:]
    # No consecutive duplicate found
    if n >= 3:
        return xs[:2] + xs[3:]
    return xs[:]  # unchanged for very short lists

