def program(xs):
    n = len(xs)
    # Too short to apply any swap
    if n < 3:
        return xs[:]

    # Find first later occurrence of the first element
    first = xs[0]
    k = None
    for i in range(1, n):
        if xs[i] == first:
            k = i
            break

    # Helper to copy and swap two positions
    def swapped(a, b):
        y = xs[:]
        y[a], y[b] = y[b], y[a]
        return y

    # Case: first three elements are identical -> bring the fourth forward
    if n >= 4 and xs[0] == xs[1] == xs[2]:
        return swapped(0, 3)

    # If the first element never repeats or repeats after position 3
    if k is None or k > 3:
        if n >= 4:
            return swapped(0, 3)
        else:
            return xs[:]

    # k is 1, 2 or 3 -> swap the elements at positions 1 and 2
    if n >= 3:
        return swapped(1, 2)
    return xs[:]

