        return xs[:]  # single element, nothing to compare
    if xs[0] < xs[1]:
        # increasing start – keep elements that are followed by a larger one, plus the last element
        result = [xs[i] for i in range(n - 1) if xs[i] < xs[i + 1]]
        result.append(xs[-1])
        return result
    else:
        # decreasing start – keep elements that are followed by a smaller one, plus the first element
        result = [xs[i] for i in range(n - 1) if xs[i] > xs[i + 1]]
        # the first element is already captured by the condition when xs[0] > xs[1],
        # but we ensure it is present in case of a single‑element list (handled earlier).
        if result and result[0] != xs[0]:
            result.insert(0, xs[0])
