    n = len(xs)
    # Helper: count consecutive drops ending at position i (xs[i] > xs[i+1])
    def drop_len_at(i):
        cnt = 0
        while i >= 0 and i + 1 < n and xs[i] > xs[i + 1]:
            cnt += 1
            i -= 1
        return cnt

    # 1. search for the right‑most valley (drop then rise)
    valley_idx = -1
    for i in range(n - 2):
        if xs[i] > xs[i + 1] < xs[i + 2]:
