        # build result according to the rule
        result = []
        # number of consecutive drops ending at valley_idx
        dl = drop_len_at(valley_idx)
        if dl <= 2:
            result.append(xs[valley_idx])          # element before the valley
        result.append(xs[valley_idx + 1])          # the valley itself
        result.append(xs[valley_idx + 2])          # the element after the valley (rise)
        return result

    # 2. no valley – use the right‑most simple drop
    last_drop = -1
    for i in range(n - 1):
        if xs[i] > xs[i + 1]:
            last_drop = i
    if last_drop != -1:
        return [xs[last_drop], xs[last_drop + 1]]

    # 3. never drops – return empty list
    return []

