    """Return the longest prefix of *xs* that ends just before the first element
    that would cause a value to appear for the second time, unless that value
    occurs later again – in which case the second occurrence is also omitted.
    """
    # First compute total frequencies of each value.
    total = {}
    for v in xs:
        total[v] = total.get(v, 0) + 1

    seen = {}
    cut = len(xs)  # default: keep whole list
    for i, v in enumerate(xs):
        cnt = seen.get(v, 0) + 1
        seen[v] = cnt
        if cnt == 2:  # this is the second occurrence of v
            # If v appears later again, we must stop BEFORE this occurrence
            if total[v] > 2:
                cut = i  # exclude this second occurrence
            else:
                cut = i + 1  # include the second occurrence
            break
    return xs[:cut]

