            res.append(xs[i])
            i += 1
            continue
        if direction is None:
            if xs[i] > xs[i-1]:
                direction = True
            elif xs[i] < xs[i-1]:
                direction = False
            else:
                # equal elements break monotonicity
                break
            res.append(xs[i])
        else:
            if (direction and xs[i] >= xs[i-1]) or (not direction and xs[i] <= xs[i-1]):
                res.append(xs[i])
            else:
                break
        i += 1
    return res

