        if run:
            # keep the zero and, if possible, the next element of the slice
            res = sel[:zpos + 1]
            if zpos + 1 < len(sel):
                res.append(sel[zpos + 1])
        else:
            # isolated zero – drop it
            res = sel[:zpos] + sel[zpos + 1:]
    except ValueError:
        # no zero in the selected slice
        res = sel
        # if the slice starts and ends with the same value, drop the last one
        if len(res) > 1 and res[0] == res[-1]:
            res = res[:-1]
    return res

