def program(xs):
    if not xs:
        return []
    v = xs[-1]
    # work on the list without the original last element
    base = xs[:-1]
    n = len(base)
    half = n // 2
    insert_pos = None
    # first try: first element > v at or after half, insert BEFORE it
    for i in range(half, n):
        if base[i] > v:
            insert_pos = i
            break
    if insert_pos is None:
        # second try: first element > v anywhere, insert AFTER it
        for i in range(n):
            if base[i] > v:
                insert_pos = i + 1
                break
    if insert_pos is None:
        # no element larger than v – insert after the first element
        insert_pos = 1 if n > 0 else 0
    # insert the copy of v
    temp = base[:insert_pos] + [v] + base[insert_pos:]
    # now deduplicate, keeping at most two copies of v (the inserted one and the final one)
    seen = set()
    result = []
    v_copies_kept = 0
    for x in temp:
        if x == v:
            # allow up to two copies of v, but prefer the inserted copy (the first we see in temp)
            if v_copies_kept < 2:
                result.append(x)
                v_copies_kept += 1
            # else discard extra copies of v
        else:
            if x not in seen:
                seen.add(x)
                result.append(x)
            # else discard duplicate of a non‑v element
    # ensure we have exactly two copies of v – if we kept only one (possible when v did not appear in base)
    if v_copies_kept == 0:
        result.append(v)
        result.append(v)
    elif v_copies_kept == 1:
        result.append(v)
    # (if we already have two copies we do nothing)
    return result

