import sys

def number_to_words(n: int) -> str:
    """Return the English word for a non‑negative integer n (0 ≤ n < 100).
    Spaces and hyphens are omitted because only the letter count matters.
    """
    ones = ["zero","one","two","three","four","five","six","seven","eight","nine"]
    teens = ["ten","eleven","twelve","thirteen","fourteen","fifteen","sixteen","seventeen","eighteen","nineteen"]
    tens = ["","","twenty","thirty","forty","fifty","sixty","seventy","eighty","ninety"]
    if n < 10:
        return ones[n]
    if n < 20:
        return teens[n-10]
    ten, one = divmod(n, 10)
    if one == 0:
        return tens[ten]
    # combine without hyphen or space as only the letter count matters
    return tens[ten] + ones[one]

def letter_count(n: int) -> int:
    """Number of letters in the English name of n (0 ≤ n < 100)."""
    return len(number_to_words(n))

def program(xs):
    # xs is a list of non‑negative ints
    if not xs:
        return []
    k = xs[0]
    tail = xs[1:]
    idx = k - 1  # position to modify (0‑based)
    if idx < 0 or idx >= len(tail):
        # if the index is out of range, just return the tail unchanged
        return tail
    orig = tail[idx]
    # decide the new value
    if orig == 0:
        new_val = len(xs)               # length of the original list
    elif orig >= 10:
        new_val = 10                    # any two‑digit (or larger) number becomes 10
    else:
        # single‑digit number: use letter count of its English name, capped at 10
        new_val = min(10, letter_count(orig))
    tail[idx] = new_val
    return tail

