def program(xs):
    n = len(xs)
    k = n // 2  # number of elements that stay in original order
    if k == 0:
        return sorted(xs)
    # Determine the k smallest values (with correct multiplicities)
    smallest_vals = sorted(xs)[:k]
    # Use a dictionary to count how many times each of these values is needed
    need = {}
    for v in smallest_vals:
        need[v] = need.get(v, 0) + 1
    first_part = []
    remaining = []
    for v in xs:
        if need.get(v, 0) > 0:
            first_part.append(v)
            need[v] -= 1
        else:
            remaining.append(v)
    return first_part + sorted(remaining)

