def program(xs):
    # Perform one full pass of odd‑even (brick) sort on a copy of xs.
    a = xs[:]
    n = len(a)
    # Even indexed phase: compare (0,1), (2,3), ...
    for i in range(0, n - 1, 2):
        if a[i] > a[i + 1]:
            a[i], a[i + 1] = a[i + 1], a[i]
    # Odd indexed phase: compare (1,2), (3,4), ...
    for i in range(1, n - 1, 2):
        if a[i] > a[i + 1]:
            a[i], a[i + 1] = a[i + 1], a[i]
    return a

