def program(xs):
    n = len(xs)
    if n < 2:
        return []
    # helper to tell if position i is a peak (1) or valley (-1) or neither (0)
    def extremum(i):
        left = xs[i-1] if i-1 >= 0 else None
        right = xs[i+1] if i+1 < n else None
        if left is None and right is None:
            return 0
        if left is None:
            if xs[i] > right:
                return 1
            if xs[i] < right:
                return -1
            return 0
        if right is None:
            if xs[i] > left:
                return 1
            if xs[i] < left:
                return -1
            return 0
        # strict comparison with both neighbours
        if xs[i] > left and xs[i] > right:
            return 1
        if xs[i] < left and xs[i] < right:
            return -1
        return 0
    # find first extremum
    start = None
    start_type = None
    for i in range(n):
        t = extremum(i)
        if t != 0:
            start = i
            start_type = t
            break
    if start is None:
        return []
    # build alternating slice
    res = [xs[start]]
    expect = -start_type  # next should be opposite type
    i = start + 1
    while i < n:
        t = extremum(i)
        if t == expect:
            res.append(xs[i])
            expect = -expect
            i += 1
        else:
            # stop when pattern would break (including non‑extremum positions)
            break
    # post‑process according to length rules
    if len(res) >= 2:
        return res
    # length 1 case: return it only if it appears elsewhere in the list
    if xs.count(res[0]) > 1:
        return res
    return []

