def program(xs):
    """Return the list of numbers from min(xs) to max(xs) with step 2,
    keeping the parity of the minimum value.
    """
    if not xs:
        return []
    lo = min(xs)
    hi = max(xs)
    # Ensure the upper bound has the same parity as lo
    if (hi - lo) % 2 != 0:
        hi -= 1
    return list(range(lo, hi + 1, 2))

