def program(xs):
    """Return a list containing, for each value that appears more than once in xs,
    that value repeated (frequency‑1) times. The groups are ordered by the
    first occurrence of each value in xs."""
    cnt = collections.Counter(xs)
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            if cnt[x] > 1:
                result.extend([x] * (cnt[x] - 1))
    return result

