    """Transform xs according to the rule inferred from the examples.
    Steps:
    1. Collapse consecutive duplicates.
    2. Walk stepwise between each consecutive pair, emitting all integers
       between them inclusive, without repeating the meeting point.
    """
    if not xs:
        return []
    # 1. compress consecutive duplicates
    comp = [xs[0]]
    for v in xs[1:]:
        if v != comp[-1]:
            comp.append(v)
    # 2. build the result by walking between each pair
    res = []
    for a, b in zip(comp, comp[1:]):
        if a <= b:
            seq = list(range(a, b + 1))
        else:
            seq = list(range(a, b - 1, -1))
        if not res:
            res.extend(seq)
        else:
            # skip the first element to avoid duplication of the joint point
            res.extend(seq[1:])
    # If there was only one distinct value, the loop adds nothing
    if not res:
        res = comp
    return res

def program(xs):
    """Transform the list according to the inferred rule.
    Starting from the first element, fill in all intermediate integers
    between successive elements, moving up or down one step at a time.
    """
    if not xs:
        return []
    result = [xs[0]]
    for y in xs[1:]:
        prev = result[-1]
        if y > prev:
            result.extend(range(prev + 1, y + 1))
        elif y < prev:
            result.extend(range(prev - 1, y - 1, -1))
        # if y == prev, nothing is added
    return result

def program(xs):
    """Transform the input list as described.
    1. Remove consecutive duplicates to get turning points.
    2. Interpolate between each successive pair with steps of +/-1.
    """
    if not xs:
        return []
    # Step 1: compress consecutive duplicates
    points = [xs[0]]
    for v in xs[1:]:
        if v != points[-1]:
            points.append(v)
    # If only one distinct value, return it
    if len(points) == 1:
        return points.copy()
    # Step 2: interpolate
    res = []
    for i in range(len(points) - 1):
        a = points[i]
        b = points[i + 1]
        step = 1 if b > a else -1
        if i == 0:
            # start with the first turning point
            res.append(a)
        # generate values from a+step up to and including b
        for val in range(a + step, b + step, step):
            res.append(val)
    return res

