def program(xs):
    """Return a list where each adjacent pair in xs is expanded with
    consecutive integers stepping by +1 or -1, without duplicating the
    connecting endpoints.
    """
    if not xs:
        return []
    result = [xs[0]]
    for a, b in zip(xs, xs[1:]):
        if a == b:
            continue
        step = 1 if b > a else -1
        cur = a + step
        while True:
            result.append(cur)
            if cur == b:
                break
            cur += step
    return result

