def program(xs):
    """Return the list obtained by splitting xs at zeros, discarding the zeros,
    reversing each non‑zero block, and concatenating the results.
    """
    result = []
    segment = []
    for x in xs:
        if x == 0:
            # End of a segment – reverse it and add to result
            if segment:
                result.extend(reversed(segment))
                segment.clear()
        else:
            segment.append(x)
    # Append the last segment if any
    if segment:
        result.extend(reversed(segment))
    return result

